-- After 18, as the agent user: the state the catalog shows it, a zero-row read of each table, and whether it may read the REORG-pending flag.
SELECT VARCHAR(TABNAME, 18) AS TABNAME, STATUS FROM SYSCAT.TABLES WHERE TABSCHEMA = 'APP' AND TABNAME LIKE 'LIBREDB_PS_%' ORDER BY 1;
SELECT * FROM APP.LIBREDB_PS_CHECK WHERE 1 = 0;
SELECT * FROM APP.LIBREDB_PS_REORG WHERE 1 = 0;
-- The same tables read in full, which the states do refuse.
SELECT * FROM APP.LIBREDB_PS_CHECK;
SELECT * FROM APP.LIBREDB_PS_REORG;
SELECT VARCHAR(TABNAME, 18) AS TABNAME, REORG_PENDING FROM SYSIBMADM.ADMINTABINFO WHERE TABSCHEMA = 'APP' AND TABNAME LIKE 'LIBREDB_PS_%' ORDER BY 1;
SELECT VARCHAR(TABNAME, 18) AS TABNAME, REORG_PENDING FROM TABLE (SYSPROC.ADMIN_GET_TAB_INFO('APP', 'LIBREDB_PS_REORG')) AS t;
